create or replace function public.staff_account_workspace_defaults() returns trigger language plpgsql security definer set search_path=public as $func$ begin if new.login_slug is null or btrim(new.login_slug)='' then new.login_slug:=public.generate_staff_login_slug(new.name); end if; if new.primary_branch_id is null then select id into new.primary_branch_id from public.branches where store_id=new.store_id order by is_default desc, created_at asc limit 1; end if; return new; end $func$;
drop trigger if exists staff_account_workspace_defaults on public.staff_accounts;
create trigger staff_account_workspace_defaults before insert or update of name,store_id,login_slug,primary_branch_id on public.staff_accounts for each row execute function public.staff_account_workspace_defaults();
create or replace function public.staff_login_profile(_slug text) returns jsonb language sql stable security definer set search_path=public as $func$ select coalesce((select jsonb_build_object('id',s.id,'store_id',s.store_id,'name',s.name,'role',s.role,'is_active',s.is_active,'login_slug',s.login_slug,'primary_branch_id',s.primary_branch_id,'store_name',st.name) from public.staff_accounts s join public.stores st on st.id=s.store_id where s.login_slug=lower(btrim(_slug)) limit 1),'{}'::jsonb) $func$;
revoke all on function public.staff_login_profile(text) from public;
grant execute on function public.staff_login_profile(text) to anon, authenticated;
create or replace function public.staff_assign_branch(_staff_id uuid,_branch_id uuid,_can_sell boolean default true,_can_view_reports boolean default false,_can_manage_inventory boolean default false,_can_manage_customers boolean default false,_can_manage_orders boolean default false,_can_manage_expenses boolean default false) returns boolean language plpgsql security definer set search_path=public as $func$ declare sid uuid; uid uuid:=auth.uid(); begin select store_id into sid from public.staff_accounts where id=_staff_id; if sid is null or not private.has_store_role(sid,uid,array['owner'::public.store_role,'manager'::public.store_role]) then raise exception 'Not authorized'; end if; if not exists(select 1 from public.branches where id=_branch_id and store_id=sid) then raise exception 'Branch does not belong to this store'; end if; insert into public.staff_branch_access(store_id,staff_id,branch_id,can_sell,can_view_reports,can_manage_inventory,can_manage_customers,can_manage_orders,can_manage_expenses) values(sid,_staff_id,_branch_id,_can_sell,_can_view_reports,_can_manage_inventory,_can_manage_customers,_can_manage_orders,_can_manage_expenses) on conflict(staff_id,branch_id) do update set can_sell=excluded.can_sell,can_view_reports=excluded.can_view_reports,can_manage_inventory=excluded.can_manage_inventory,can_manage_customers=excluded.can_manage_customers,can_manage_orders=excluded.can_manage_orders,can_manage_expenses=excluded.can_manage_expenses,updated_at=now(); update public.staff_accounts set primary_branch_id=coalesce(primary_branch_id,_branch_id) where id=_staff_id; return true; end $func$;
create or replace function public.staff_remove_branch(_staff_id uuid,_branch_id uuid) returns boolean language plpgsql security definer set search_path=public as $func$ declare sid uuid; uid uuid:=auth.uid(); begin select store_id into sid from public.staff_accounts where id=_staff_id; if sid is null or not private.has_store_role(sid,uid,array['owner'::public.store_role,'manager'::public.store_role]) then raise exception 'Not authorized'; end if; delete from public.staff_branch_access where staff_id=_staff_id and branch_id=_branch_id; update public.staff_accounts set primary_branch_id=(select branch_id from public.staff_branch_access where staff_id=_staff_id order by is_primary desc,created_at asc limit 1) where id=_staff_id and primary_branch_id=_branch_id; return true; end $func$;
revoke all on function public.staff_assign_branch(uuid,uuid,boolean,boolean,boolean,boolean,boolean,boolean) from public; grant execute on function public.staff_assign_branch(uuid,uuid,boolean,boolean,boolean,boolean,boolean,boolean) to authenticated;
revoke all on function public.staff_remove_branch(uuid,uuid) from public; grant execute on function public.staff_remove_branch(uuid,uuid) to authenticated;
